function ACTES_RANK(it) {
  var t = Array.isArray(it) ? String(it[0] || '') : String((it && (it.description || it.name)) || '').split(' | ')[0];
  var k = Array.isArray(it) ? '' : String((it && it.key) || '');
  if (/كنشات|MC4/i.test(t) || /mc4/i.test(k)) return 9;
  if (/كابل/.test(t) || /^cable/i.test(k)) return 10;
  if (/كنترول\s*ربط\s*(ا|إ)ضافي/.test(t)) return 5;
  if (/كنترول/.test(t)) return 4;
  if (/صندوق\s*حماية\s*البطاريات/.test(t)) return 6;
  if (/تيار\s*مستمر|حماية\s*DC|^dc[:]/i.test(t) || /^dc[:]/i.test(k)) return 7;
  if (/تيار\s*متردد|حماية\s*AC|تجميع/i.test(t) || /^ac[:]/i.test(k)) return 8;
  if (/^panel[:]/i.test(k) || (/(ألواح|الواح|لواح)/.test(t) && !/لوحة|لوحات|صندوق/.test(t))) return 1;
  if (/^inverter[:]/i.test(k) || /(إ|ا|أ|اي)نف(ي)?رتر/.test(t)) return 2;
  if (/^(battery|ess|bms)[:]/i.test(k) || /بطاري|كبينة/.test(t)) return 3;
  return 11;
}
function ACTES_SORT(arr) {
  return arr.map(function (it, i) { return { it: it, r: ACTES_RANK(it), i: i }; })
    .sort(function (a, b) { return (a.r - b.r) || (a.i - b.i); })
    .map(function (x) { return x.it; });
}

