function num(s, re) { var m = String(s || '').match(re); return m ? m[1] : ''; }

// إيجاد أقرب بطاقة صنف في ITEM_DESC عند عدم تطابق المفتاح
function matchItemDesc(key, name) {
  try {
    if (key && ITEM_DESC[key] && ITEM_DESC[key].desc) { return ITEM_DESC[key].desc; }
    var n = String(name || '');
    if (/بطاري/.test(n) && /هيثيوم|HITHIUM|HTHIUM|HeroEE|LEGND112S/i.test(n) && /16/.test(n)) { return (/LEGND112S|هاي\s*فولتج/i.test(n) ? ITEM_DESC['battery:16:hv'] : ITEM_DESC['battery:16:hithium']).desc; }
    if (!n) { return ''; }
    var cat = '';
    if (/(?:^|\s)(?:لوح|الواح|ألواح)\s*(?:طاقة|شمسية)|panel|PV\s*module/i.test(n)) { cat = 'panel'; }
    else if (!/لوح|صندوق/i.test(n) && /(?:إ|ا|أ|اي)نف(?:ي)?رتر|inverter/i.test(n)) { cat = 'inverter'; }
    else if (/بطاري|battery/i.test(n)) { cat = 'battery'; }
    else if (/كابل|cable/i.test(n)) { cat = 'cable'; }
    if (!cat) { return ''; }
    var val = num(n, /(\d+(?:\.\d+)?)\s(?:كيلو|وات|واط|kw|kwh|w|مم|mm)/i);
    var ph3 = /(3\sفاز|ثري\s*فاز|three)/i.test(n) ? '3' : '1';
    var keys = Object.keys(ITEM_DESC);
    var best = '';
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      if (k.indexOf(cat) !== 0) { continue; }
      var parts = k.split(':');
      if (val && parts[1] === String(val)) {
        if (cat !== 'inverter' || parts.length < 3 || parts[2] === ph3) { return ITEM_DESC[k].desc; }
      }
      if (!best) { best = ITEM_DESC[k].desc; }
    }
    return '';
  } catch (e) { return ''; }
}

// الدالة الرئيسية: تُعيد وصفاً بمواصفات كاملة دائماً
function specFallback(desc, key) {
  var d = String(desc || '').trim();
  if (d.split(' | ').length >= 4 || d.length >= 150) { return d; }
  var full = matchItemDesc(key, d);
  if (full) { return full; }
  // عند غياب بطاقة مطابقة، نعرض البيانات المسجلة فقط بلا مواصفات مخمنة.
  return d;
}

