}

// 2. نص رسالة عرض السعر (الاسم + القدرة + الكمية + السعر)
function getQuoteTextView(itemCode, qty) {
  var it = UNIFIED_CATALOG[itemCode] || {};
  var p = it.price_usd != null ? (it.price_usd * (qty || 1)) + ' $' : 'حسب الكمية';
  return (it.name || itemCode) + ' | ' + (it.capacity || '') + ' | العدد: ' + (qty || 1) + ' | السعر: ' + p;
}

// 3. مواصفات PDF عرض السعر (المواصفات مرتبة كل وصف في سطر)
function getPdfSpecsView(itemCode) {
  var it = UNIFIED_CATALOG[itemCode] || {};
  return Array.isArray(it.specs) ? it.specs.join('\n') : '';
}

