    addUnique(pv, pick([/مدى.*MPPT|MPPT.*\(|MPPT:/i]));
    addUnique(inv, pv.join(' | '));
    var mppt = [];
    addUnique(mppt, pick([/عدد MPPT|عدد المنظمات|MPPT:/i]));
    addUnique(mppt, pick([/تيار دخل PV|تيار.*الالواح|PV.*Current/i]));
