  // حذف نهائي للملاحظة القديمة رقم 1 ورقم 4 من جميع العروض.
  L.push('الأسعار غير شاملة أعمال التركيب ما لم يُذكر خلاف ذلك.'); // النص النهائي الثابت للملاحظة الأولى
  if (__cableIt && parseFloat(String(__cableIt.quantity || '')) === 1) {
    L.push('كمية الكابل (1 متر) لتحديد سعر المتر، ويُحدد الطول الفعلي حسب مسافة الموقع.');
  } else if (__isComQuote) {
    var qtyTxt = __cableIt ? String(__cableIt.quantity || '').replace(/[^0-9.,]/g, '') : '';
    var prcTxt = __cableIt ? money(__cableIt.price) : '';
    var cline = 'الكابل يُحسب على حسب المسافة بالمتر';
    if (qtyTxt) { cline += '، والكمية المدرجة (' + esc(qtyTxt) + ' متر) تقديرية'; }
    if (prcTxt && prcTxt !== '0.00') { cline += ' بسعر ' + esc(prcTxt) + ' للمتر الواحد'; }
    cline += '، ويُحتسب المبلغ النهائي حسب الطول الفعلي المقاس في الموقع.';
    L.push(cline);
  } else {
    L.push('كمية الكابل بالمتر وهي تقديرية ويتم تحديد الطول النهائي حسب طبيعة الموقع.');
  }
  return L.map(function (t, i) { return (i + 1) + '. ' + t; }).join('<br/>');
}
html = html.split('{{notes}}').join(__notesHtml());
html = html.split('{{tableFill}}').join('');

var vals = {
  reportDate: reqDate + ' ' + new Date(Date.now()+3*3600*1000).toISOString().substr(11,8),
  pageNo: '1',
  printedBy: 'مجد-8',
  quoteNumber: qnum,
  customerTitle: 'الأخ',
  customerName: cname,
  customerPhone: cphone,
  customerLocation: cloc,
  currency: q.currency || 'الدولار الأمريكي',
  date: reqDate,
  subtotal: money(subtotal),
  discount: money(discount),
  total: money(grand),
  totalUSD: money(usd),
  totalSAR: money(usd*530/140),
  totalYER: money(usd*530),
  reportDate: reqDate + ' ' + new Date(Date.now()+3*3600*1000).toISOString().substr(11,8),
  pageNo: '1',
  printedBy: 'مجد-8',
  notes: ''
};
Object.keys(vals).forEach(function (k) {
  html = html.split('{{' + k + '}}').join(esc(vals[k]));
});
html = html.replace(/\{\{[a-zA-Z]+\}\}/g, '');

var safeName = String(cname).replace(/[\\/:*?"<>|]/g, ' ').trim();
var filename = 'عرض سعر ' + qnum + ' - ' + safeName + ' - ' + reqDate.split('/').join('-') + '.pdf';

var workId = 'quote_' + qnum.replace(/[^A-Za-z0-9]/g, '') + '_' + Date.now();



// ===== إزالة أسماء ماركات وأنواع الكابلات من HTML النهائي =====
// هذا تنظيف أخير على النص الناتج نفسه، حتى لا تظهر أي ماركة حتى لو دخلت من بيانات العرض أو المواصفات.
var __cableBrandFinalRe = /مسك|سيفال|سفال|الكان|كابل\s*تركي|(?<![ء-ي])تركي(?![ء-ي])|صيني|سعودي|MISK|MISK CABLE|SEFAL|CEFAL|ALKAN|AL-KAN|TURKISH|TURKEY|CHINA|SAUDI/ig;
html = html.replace(__cableBrandFinalRe, '');
html = html.replace(/إكسسوارات ومستلزمات\s+الب\s+والكنشات/gi, 'إكسسوارات ومستلزمات التركيب والكنشات');
html = html.replace(/أعمال\s+الب\b/gi, 'أعمال التركيب'); html = html.replace(/أعمال\s*الب\b/gi, 'أعمال التركيب'); html = html.replace(/أعمال\s*الـ?ب\b/gi, 'أعمال التركيب');
html = html.replace(/إكسسوارات ومستلزمات\s+الـب\s+والكنشات/gi, 'إكسسوارات ومستلزمات التركيب والكنشات');
html = html.replace(/أعمال\s+الـب\b/gi, 'أعمال التركيب');
html = html.replace(/صنف\s+أصلي\s+جديد/gi, '');
html = html.replace(/\s{2,}/g, ' ').replace(/\s*\|\s*\|\s*/g, ' | ');
var __nowY = new Date(Date.now() + 3 * 3600 * 1000);
var __hh24 = __nowY.getUTCHours();
var __ampm = __hh24 >= 12 ? 'PM' : 'AM';
var __hh12 = ((__hh24 + 11) % 12) + 1;
var __reportClock = two(__hh12) + ':' + two(__nowY.getUTCMinutes()) + ':' + two(__nowY.getUTCSeconds());
var __reportDateText = __ampm + ' ' + __reportClock + ' ' + reqDate;

// ===== نص عرض السعر الرسمي: يُستخرج من جدول الـ PDF النهائي نفسه (نفس الأسماء والترتيب) =====
function __unesc(s){ return String(s||'').replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&').replace(/\s+/g,' ').trim(); }
var __qt = '';
try {
  var __re = /<td class="desc"[^>]*>\s*<span class="dttl">([\s\S]*?)<\/span>[\s\S]*?<\/td>\s*<td[^>]*>([\s\S]*?)<\/td>\s*<td[^>]*>([\s\S]*?)<\/td>\s*<td[^>]*>([\s\S]*?)<\/td>\s*<td[^>]*>([\s\S]*?)<\/td>/g;
  var __m, __n = 0, __L = [];
  while ((__m = __re.exec(html))) {
    __n++;
    __L.push(__n + '. ' + __unesc(__m[1]));
    __L.push('الكمية: ' + __unesc(__m[3]) + ' ' + __unesc(__m[2]));
    __L.push('سعر الوحدة: ' + __unesc(__m[4]));
    __L.push('الإجمالي: ' + __unesc(__m[5]));
    __L.push('━━━━━━━━━━━━━━━━━━━━');
  }
  if (__n) {
    __qt = '📋 عرض السعر' + (qnum ? ' رقم ' + qnum : '') + '\n━━━━━━━━━━━━━━━━━━━━\nالعميل: ' + (cname || '...........') + '\n\n' + __L.join('\n') + '\n💰 الإجمالي الكلي: ' + money(grand) + ' $';
  }
} catch (e) { __qt = ''; }
return [{ json: {
  quote_text: __qt,
  phone: sm.phone,
  phone_number_id: sm.phone_number_id,
  quote_number: qnum,
  quote_name: q.name,
  customer_name: cname,
  request_date: reqDate,
  report_date_text: __reportDateText,
  printed_by: 'مجد-8',
  filename: filename,
  work_id: workId,
  html_b64: Buffer.from(html, 'utf8').toString('base64'),
  html: html
} }]
